eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   IPN_MATEMATICAS_TOPICS: () => (/* binding */ IPN_MATEMATICAS_TOPICS)\n/* harmony export */ });\n/** Temario ultra-detallado de Matemáticas (Pensamiento Matemático) — Examen IPN. */ const IPN_MATEMATICAS_TOPICS = [\n    {\n        \"id\": \"ipn-mat-1-1\",\n        \"codigo\": \"1.1\",\n        \"titulo\": \"Razonamiento Matem\\xe1tico y Pensamiento Espacial\",\n        \"orden\": 1,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"ipn-mat-1-1-1\",\n                \"codigo\": \"1.1.1\",\n                \"titulo\": \"Sucesiones num\\xe9ricas complejas\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Identificaci\\xf3n de patrones en sucesiones de segundo orden (donde la diferencia com\\xfan no es constante en el primer nivel, sino en el segundo) y sucesiones alternas o intercaladas (a_n = p_n + q_n). Uso de la f\\xf3rmula general para el t\\xe9rmino en\\xe9simo de una progresi\\xf3n aritm\\xe9tica (a_n = a_1 + (n-1)d) y geom\\xe9trica (a_n = a_1 \\xb7 r^(n-1)).\"\n            },\n            {\n                \"id\": \"ipn-mat-1-1-2\",\n                \"codigo\": \"1.1.2\",\n                \"titulo\": \"Sucesiones alfanum\\xe9ricas con simetr\\xeda\",\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Series que combinan incrementos num\\xe9ricos con saltos alfab\\xe9ticos bas\\xe1ndose en el abecedario oficial de 27 letras (omitiendo la ch y la ll, pero incluyendo la \\xf1).\"\n            },\n            {\n                \"id\": \"ipn-mat-1-1-3\",\n                \"codigo\": \"1.1.3\",\n                \"titulo\": \"Series espaciales y rotaciones 3D\",\n                \"orden\": 3,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Giros de figuras bidimensionales sobre ejes imaginarios (X, Y). En matrices de figuras de 3\\xd73, identificar el patr\\xf3n de rotaci\\xf3n horaria/antihoraria (frecuentemente combinada con incrementos angulares de 45\\xb0, 90\\xb0 o 135\\xb0) y cambios en el sombreado o tramado de las piezas.\"\n            },\n            {\n                \"id\": \"ipn-mat-1-1-4\",\n                \"codigo\": \"1.1.4\",\n                \"titulo\": \"Despliegue y armado de poliedros\",\n                \"orden\": 4,\n                \"status\": \"publicado\",\n                \"descripcion\": 'Visualizaci\\xf3n mental de cubos desarmados (desarrollos planos en forma de cruz, de \"T\", etc.). El examen del IPN exige determinar qu\\xe9 cara queda opuesta a cu\\xe1l otra o qu\\xe9 s\\xedmbolos quedan contiguos tras armar la figura tridimensional.'\n            },\n            {\n                \"id\": \"ipn-mat-1-1-5\",\n                \"codigo\": \"1.1.5\",\n                \"titulo\": \"Conteo de cubos y vistas ortogonales\",\n                \"orden\": 5,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Determinaci\\xf3n del n\\xfamero exacto de bloques en arreglos tridimensionales complejos que incluyen piezas ocultas. Traducci\\xf3n de figuras 3D a sus vistas bidimensionales normalizadas: Planta (vista superior), Alzado (vista frontal) y Perfil (vista lateral).\"\n            }\n        ]\n    },\n    {\n        \"id\": \"ipn-mat-1-2\",\n        \"codigo\": \"1.2\",\n        \"titulo\": \"\\xc1lgebra\",\n        \"orden\": 2,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"ipn-mat-1-2-1\",\n                \"codigo\": \"1.2.1\",\n                \"titulo\": \"Operaciones y divisi\\xf3n sint\\xe9tica\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Algoritmo de la divisi\\xf3n larga de polinomios y aplicaci\\xf3n estricta de la Regla de Ruffini (Divisi\\xf3n Sint\\xe9tica) para simplificar polinomios racionales cuando el divisor es de la forma x \\xb1 c. Aplicaci\\xf3n pr\\xe1ctica del Teorema del Residuo para evaluar funciones polinomiales complejas sin hacer la divisi\\xf3n.\"\n            },\n            {\n                \"id\": \"ipn-mat-1-2-2\",\n                \"codigo\": \"1.2.2\",\n                \"titulo\": 'Productos notables avanzados y factorizaci\\xf3n \"filtro\"',\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Desarrollo mec\\xe1nico de binomios con coeficientes fraccionarios o exponentes algebraicos. Factorizaci\\xf3n exhaustiva de trinomios por el m\\xe9todo de tijera o cruz (ax\\xb2 + bx + c) y agrupaciones que involucran identidades ocultas (como completar un trinomio cuadrado perfecto dentro de una diferencia de cuadrados). Suma y diferencia de cubos aplicadas a simplificaci\\xf3n de fracciones algebraicas complejas.\"\n            },\n            {\n                \"id\": \"ipn-mat-1-2-3\",\n                \"codigo\": \"1.2.3\",\n                \"titulo\": \"Sistemas de ecuaciones simult\\xe1neas\",\n                \"orden\": 3,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Resoluci\\xf3n exacta de sistemas de 3\\xd73 mediante el m\\xe9todo de eliminaci\\xf3n gaussiana o la Regla de Cramer (Determinantes por el m\\xe9todo de Sarrus). Planteamiento algebraico riguroso a partir de problemas con enunciados t\\xe9cnicos.\"\n            },\n            {\n                \"id\": \"ipn-mat-1-2-4\",\n                \"codigo\": \"1.2.4\",\n                \"titulo\": \"N\\xfameros complejos\",\n                \"orden\": 4,\n                \"status\": \"publicado\",\n                \"descripcion\": \"\\xc1lgebra de los n\\xfameros imaginarios (i^n con reducci\\xf3n de potencias dividiendo entre 4). Conversi\\xf3n de la forma bin\\xf3mica (z = a + bi) a la forma polar o trigonom\\xe9trica (z = r(cos θ + i sen θ)) utilizando el m\\xf3dulo r = √(a\\xb2 + b\\xb2) y el argumento exacto θ = arctan(b/a) seg\\xfan el cuadrante. Operaciones de multiplicaci\\xf3n y divisi\\xf3n en forma polar (Teorema de Moivre).\"\n            }\n        ]\n    },\n    {\n        \"id\": \"ipn-mat-1-3\",\n        \"codigo\": \"1.3\",\n        \"titulo\": \"Geometr\\xeda y Trigonometr\\xeda\",\n        \"orden\": 3,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"ipn-mat-1-3-1\",\n                \"codigo\": \"1.3.1\",\n                \"titulo\": \"Geometr\\xeda euclidiana\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"descripcion\": \"\\xc1ngulos complementarios, suplementarios y conjugados. Teoremas de \\xe1ngulos formados por rectas paralelas cortadas por una secante (alternos internos, alternos externos, correspondientes). Teorema de Tales aplicado a la semejanza de tri\\xe1ngulos (escalonamiento de sombras y estructuras).\"\n            },\n            {\n                \"id\": \"ipn-mat-1-3-2\",\n                \"codigo\": \"1.3.2\",\n                \"titulo\": \"Funciones trigonom\\xe9tricas y c\\xedrculo unitario\",\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Definici\\xf3n de funciones fundamentales y rec\\xedprocas en el plano cartesiano. Deducci\\xf3n anal\\xedtica de los signos de las funciones en los cuadrantes I, II, III y IV. Uso del c\\xedrculo unitario para hallar los valores exactos de \\xe1ngulos cuadrantales (0, π/2, π, 3π/2, 2π) y notables (30\\xb0, 45\\xb0, 60\\xb0) expresados preferentemente en radianes.\"\n            },\n            {\n                \"id\": \"ipn-mat-1-3-3\",\n                \"codigo\": \"1.3.3\",\n                \"titulo\": \"Identidades y ecuaciones trigonom\\xe9tricas complejas\",\n                \"orden\": 3,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Simplificaci\\xf3n de expresiones trigonom\\xe9tricas largas utilizando identidades pitag\\xf3ricas, de cociente y las identidades para \\xe1ngulo doble (sen(2x) = 2 sen x cos x, cos(2x) = cos\\xb2x − sen\\xb2x). Resoluci\\xf3n de ecuaciones trigonom\\xe9tricas lineales o cuadr\\xe1ticas que requieren factorizar la funci\\xf3n e identificar todas las soluciones reales dentro del intervalo [0, 2π].\"\n            }\n        ]\n    },\n    {\n        \"id\": \"ipn-mat-1-4\",\n        \"codigo\": \"1.4\",\n        \"titulo\": \"Geometr\\xeda anal\\xedtica\",\n        \"orden\": 4,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"ipn-mat-1-4-1\",\n                \"codigo\": \"1.4.1\",\n                \"titulo\": \"La l\\xednea recta\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Conversi\\xf3n fluida entre todas las formas de la ecuaci\\xf3n (General, Ordinaria, Sim\\xe9trica y Punto-Pendiente). Deducci\\xf3n de la ecuaci\\xf3n de una recta que pasa por un punto dado y es paralela o perpendicular a otra recta conocida. C\\xe1lculo de la distancia m\\xe1s corta de un punto a una recta: d = |Ax₁ + By₁ + C| / √(A\\xb2 + B\\xb2).\"\n            },\n            {\n                \"id\": \"ipn-mat-1-4-2\",\n                \"codigo\": \"1.4.2\",\n                \"titulo\": \"Circunferencia\",\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Deducci\\xf3n de la ecuaci\\xf3n general a partir del centro C(h,k) y el radio r. Proceso inverso: transformar la ecuaci\\xf3n general x\\xb2 + y\\xb2 + Dx + Ey + F = 0 a su forma ordinaria (x−h)\\xb2 + (y−k)\\xb2 = r\\xb2 completando trinomios cuadrados perfectos para determinar el centro y la longitud del radio.\"\n            },\n            {\n                \"id\": \"ipn-mat-1-4-3\",\n                \"codigo\": \"1.4.3\",\n                \"titulo\": \"Par\\xe1bola\",\n                \"orden\": 3,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Estudio de las 4 orientaciones posibles con v\\xe9rtice fuera del origen V(h,k) (horizontales que abren a la derecha/izquierda y verticales que abren hacia arriba/abajo). Obtenci\\xf3n anal\\xedtica y gr\\xe1fica de sus elementos esenciales: Foco, Directriz, V\\xe9rtice, Eje focal y longitud del Lado Recto (LR = |4p|).\"\n            },\n            {\n                \"id\": \"ipn-mat-1-4-4\",\n                \"codigo\": \"1.4.4\",\n                \"titulo\": \"Elipse\",\n                \"orden\": 4,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Ecuaciones ordinarias para elipses horizontales y verticales con centro en C(h,k). Relaci\\xf3n pitag\\xf3rica fundamental entre sus semiejes: a\\xb2 = b\\xb2 + c\\xb2 (donde a es el semieje mayor, b el semieje menor y c la distancia focal). Determinaci\\xf3n de v\\xe9rtices, co-v\\xe9rtices, focos, excentricidad (e = c/a, donde 0 < e < 1) y longitud de sus dos lados rectos (LR = 2b\\xb2/a).\"\n            },\n            {\n                \"id\": \"ipn-mat-1-4-5\",\n                \"codigo\": \"1.4.5\",\n                \"titulo\": \"Hip\\xe9rbola\",\n                \"orden\": 5,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Ecuaciones ordinarias para hip\\xe9rbolas horizontales y verticales con centro en C(h,k). Relaci\\xf3n matem\\xe1tica entre sus ejes: c\\xb2 = a\\xb2 + b\\xb2 (donde a es el semieje real y b el semieje imaginario). C\\xe1lculo exacto de su excentricidad (e = c/a, donde e > 1) y de las ecuaciones de sus as\\xedntotas lineales utilizando las pendientes \\xb1b/a o \\xb1a/b seg\\xfan corresponda.\"\n            }\n        ]\n    },\n    {\n        \"id\": \"ipn-mat-1-5\",\n        \"codigo\": \"1.5\",\n        \"titulo\": \"C\\xe1lculo diferencial\",\n        \"orden\": 5,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"ipn-mat-1-5-1\",\n                \"codigo\": \"1.5.1\",\n                \"titulo\": \"Funciones, dominio y rango\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Determinaci\\xf3n anal\\xedtica rigurosa del dominio de funciones compuestas (racionales con denominadores que no pueden ser cero; radicales de \\xedndice par cuyos radicandos deben ser ≥ 0; funciones logar\\xedtmicas cuyos argumentos deben ser estrictamente mayores a cero).\"\n            },\n            {\n                \"id\": \"ipn-mat-1-5-2\",\n                \"codigo\": \"1.5.2\",\n                \"titulo\": \"L\\xedmites algebraicos e indeterminaciones\",\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Evaluaci\\xf3n y eliminaci\\xf3n de indeterminaciones de la forma 0/0 utilizando factorizaci\\xf3n avanzada (conjugados, cubos, trinomios) y racionalizaci\\xf3n de radicales dobles. L\\xedmites trigonom\\xe9tricos basados en el l\\xedmite especial: lim(x→0) sen(x)/x = 1. Resoluci\\xf3n de l\\xedmites al infinito de la forma ∞/∞ comparando anal\\xedticamente los grados de los polinomios del numerador y del denominador.\"\n            },\n            {\n                \"id\": \"ipn-mat-1-5-3\",\n                \"codigo\": \"1.5.3\",\n                \"titulo\": \"Derivadas por f\\xf3rmulas directas y Regla de la Cadena\",\n                \"orden\": 3,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Aplicaci\\xf3n encadenada de f\\xf3rmulas para derivadas de productos (u\\xb7v) y cocientes (u/v). Derivaci\\xf3n de funciones trascendentes compuestas utilizando la Regla de la Cadena de forma sucesiva en funciones trigonom\\xe9tricas directas (sen u, cos u, tan u), trigonom\\xe9tricas inversas (arcsen u, arctan u), exponenciales (e^u, a^u) y logar\\xedtmicas (ln u, log_a u).\"\n            },\n            {\n                \"id\": \"ipn-mat-1-5-4\",\n                \"codigo\": \"1.5.4\",\n                \"titulo\": \"Derivaci\\xf3n impl\\xedcita\",\n                \"orden\": 4,\n                \"status\": \"publicado\",\n                \"descripcion\": \"T\\xe9cnica de derivaci\\xf3n para ecuaciones donde la variable dependiente y no est\\xe1 despejada, aplicando la derivada t\\xe9rmino a t\\xe9rmino respecto a x y despejando algebraicamente la expresi\\xf3n y′ o dy/dx.\"\n            },\n            {\n                \"id\": \"ipn-mat-1-5-5\",\n                \"codigo\": \"1.5.5\",\n                \"titulo\": \"Aplicaciones geom\\xe9tricas y optimizaci\\xf3n\",\n                \"orden\": 5,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Determinaci\\xf3n de la pendiente de la recta tangente a una curva en un punto dado; c\\xe1lculo de la ecuaci\\xf3n de la recta tangente y normal. Uso de los criterios de la primera y segunda derivada para localizar puntos cr\\xedticos, intervalos de crecimiento y decrecimiento, m\\xe1ximos y m\\xednimos relativos, puntos de inflexi\\xf3n y concavidad. Planteamiento y resoluci\\xf3n de problemas de optimizaci\\xf3n t\\xe9cnica (maximizar vol\\xfamenes de cajas, minimizar materiales de cilindros, velocidad de llenado).\"\n            }\n        ]\n    },\n    {\n        \"id\": \"ipn-mat-1-6\",\n        \"codigo\": \"1.6\",\n        \"titulo\": \"C\\xe1lculo integral\",\n        \"orden\": 6,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"ipn-mat-1-6-1\",\n                \"codigo\": \"1.6.1\",\n                \"titulo\": \"Integraci\\xf3n inmediata\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Propiedades de linealidad. Aplicaci\\xf3n directa de las f\\xf3rmulas de integraci\\xf3n para potencias (∫x^n dx), funciones exponenciales y funciones trigonom\\xe9tricas b\\xe1sicas, incluyendo el manejo correcto de las constantes de integraci\\xf3n (+C).\"\n            },\n            {\n                \"id\": \"ipn-mat-1-6-2\",\n                \"codigo\": \"1.6.2\",\n                \"titulo\": \"M\\xe9todos de integraci\\xf3n mec\\xe1nicos (filtro operativo del IPN)\",\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"ipn-mat-1-6-2-1\",\n                        \"codigo\": \"1.6.2.1\",\n                        \"titulo\": \"Cambio de variable (sustituci\\xf3n)\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\",\n                        \"descripcion\": \"Selecci\\xf3n correcta de u y su respectivo diferencial du para completar y balancear la integral con coeficientes num\\xe9ricos.\"\n                    },\n                    {\n                        \"id\": \"ipn-mat-1-6-2-2\",\n                        \"codigo\": \"1.6.2.2\",\n                        \"titulo\": \"Integraci\\xf3n por partes\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\",\n                        \"descripcion\": \"Aplicaci\\xf3n sistem\\xe1tica de la f\\xf3rmula ∫u dv = uv − ∫v du utilizando la prioridad ILATE para seleccionar la variable u.\"\n                    },\n                    {\n                        \"id\": \"ipn-mat-1-6-2-3\",\n                        \"codigo\": \"1.6.2.3\",\n                        \"titulo\": \"Fracciones parciales\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\",\n                        \"descripcion\": \"Descomposici\\xf3n de funciones racionales complejas cuando el denominador es factorizable en factores lineales no repetidos (A/(x−c₁) + B/(x−c₂)) o factores lineales repetidos, determinando el valor de las constantes mediante sistemas de ecuaciones o sustituci\\xf3n directa.\"\n                    }\n                ]\n            },\n            {\n                \"id\": \"ipn-mat-1-6-3\",\n                \"codigo\": \"1.6.3\",\n                \"titulo\": \"Integral definida y c\\xe1lculo de \\xe1reas\",\n                \"orden\": 3,\n                \"status\": \"publicado\",\n                \"descripcion\": \"Aplicaci\\xf3n del Teorema Fundamental del C\\xe1lculo para evaluar l\\xedmites de integraci\\xf3n [a, b]. C\\xe1lculo exacto del \\xe1rea bajo una curva y del \\xe1rea comprendida entre las gr\\xe1ficas de dos funciones distintas, localizando previamente los puntos de intersecci\\xf3n de las curvas mediante la igualaci\\xf3n de las ecuaciones.\"\n            }\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/ipn-temario-matematicas.ts\n");

